<script setup lang="ts">
import {ref} from 'vue'
import {api} from '../api'
import Icon from './Icon.vue'
const props=defineProps<{bookId:string;period:string}>()
const flow=ref('payable');const loading=ref('');const error=ref('');const result=ref<Record<string,any>>();const findings=ref<Record<string,any>[]>();
const money=(v:unknown)=>{const [integer,decimal='00']=String(v??'0.00').split('.');return `${integer.replace(/\B(?=(\d{3})+(?!\d))/g,',')}.${decimal.padEnd(2,'0')}`}
async function match(){loading.value='match';error.value='';try{result.value=await api(`/books/${props.bookId}/matches?flow=${flow.value}`)}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{loading.value=''}}
async function reconcile(){loading.value='bank';error.value='';try{findings.value=await api(`/books/${props.bookId}/bank-reconciliation`)}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{loading.value=''}}
</script>
<template><section class="panel spaced"><div class="panel-heading"><div><span class="section-number">04</span><h2>资金与往来核对</h2></div><span class="tiny-label">{{ period }} · 候选需复核</span></div><div class="funds-controls"><label>业务方向<select v-model="flow" aria-label="资金业务方向" :disabled="!!loading" @change="result=undefined"><option value="payable">应付 · 对外付款</option><option value="receivable">应收 · 对内收款</option></select></label><button class="button primary" :disabled="!!loading" @click="match">{{ loading==='match'?'匹配中…':'查找匹配候选' }}</button><button class="button" :disabled="!!loading" @click="reconcile">{{ loading==='bank'?'核对中…':'核对银行与账面' }}</button></div><div v-if="error" class="notice error" style="margin:0 22px 18px" role="alert">{{ error }}</div><template v-if="result"><div class="funds-summary"><span><b>{{ result.candidates.length }}</b>组完整候选</span><span><b>{{ result.partial_candidates.length }}</b>组部分候选</span><span><b>{{ result.unmatched.left.length+result.unmatched.right.length }}</b>条未匹配</span><span class="mono">{{ result.backend }}</span></div><div v-if="result.candidates.length||result.partial_candidates.length" class="table-wrap"><table><thead><tr><th>候选性质</th><th>发票 / 左侧记录</th><th>资金 / 右侧记录</th><th class="number">候选金额</th><th>状态</th></tr></thead><tbody><tr v-for="(c,i) in [...result.candidates,...result.partial_candidates]" :key="i"><td>{{ c.allocation_status==='partial_candidate'?'部分结算候选':'全额匹配候选' }}</td><td class="mono wrap-text">{{ c.left_ids.join(' / ') }}</td><td class="mono wrap-text">{{ c.right_ids.join(' / ') }}</td><td class="number">{{ money(c.amount) }}</td><td><span class="badge warning">待复核 · 未核销</span></td></tr></tbody></table></div><div v-else class="small-empty">当前条件未找到匹配候选。请检查方向、来源记录及业务关系。</div><details v-if="result.limited_groups.length" class="funds-details"><summary>有 {{ result.limited_groups.length }} 个分组达到计算边界</summary><pre>{{ JSON.stringify(result.limited_groups,null,2) }}</pre></details><details v-if="result.unmatched.left.length||result.unmatched.right.length" class="funds-details"><summary>查看未匹配记录</summary><pre>{{ JSON.stringify(result.unmatched,null,2) }}</pre></details></template><div v-if="findings" class="bank-findings"><h3>银行与账面核对结果</h3><div v-for="(f,i) in findings" :key="i"><span class="badge warning">需复核</span><strong>{{ f.title }}</strong><p>{{ f.explanation }}</p></div><p v-if="!findings.length" class="text-success">已实现的银行核对规则未发现差异；不代表全部业务已核销或处理正确。</p></div><div class="panel-foot"><Icon name="info" :size="14"/><span>候选可能重叠，不会自动核销。未达账项和资料缺失也可能形成差异。</span></div></section></template>
